CREATE TABLE "information_fiscale" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "information_fiscale_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"utilisateur_id" text NOT NULL,
	"revenu_net_imposable" bigint NOT NULL,
	"situation_familiale" text NOT NULL,
	"nombre_enfants" integer NOT NULL,
	"mis_a_jour_le" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "information_fiscale_utilisateur_id_unique" UNIQUE("utilisateur_id")
);
